import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { makeStyles } from '@material-ui/core/styles';
import { Box, Card, CardContent, Typography, Grid } from '@material-ui/core';

const useStyles = makeStyles((theme) => ({
  root: {
    height: '100%',
    transition: 'all 0.25s',
    cursor: 'pointer',
    '&:hover': {
      transform: 'translateY(-5px)',
    },
  },
  img: {
    width: '5rem',
    height: '5rem',
    objectFit: 'contain',
  },
  subFeatureContainer: {
    marginTop: theme.spacing(2),
  },
  subFeatureCard: {
    marginTop: theme.spacing(1),
  }
}));

function FeatureBox({ imgUrl, title, subTitle, to, subFeatures }) {
  const classes = useStyles();
  const [showSubFeatures, setShowSubFeatures] = useState(false);

  const handleClick = () => {
    if (subFeatures) {
      setShowSubFeatures(!showSubFeatures);
    }
  };

  return (
    <>
      <Card className={classes.root} onClick={handleClick}>
        {!to ? (
          <CardContent>
            <Box display="flex" alignItems="center" mb={2}>
              <img className={classes.img} src={imgUrl} alt={title} />
              <Box ml={3}>
                <Typography variant="h6" component="h3">
                  {title}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {subTitle}
                </Typography>
              </Box>
            </Box>
          </CardContent>
        ) : (
          <Link to={to} style={{ textDecoration: 'none', color: 'inherit' }}>
            <CardContent>
              <Box display="flex" alignItems="center" mb={2}>
                <img className={classes.img} src={imgUrl} alt={title} />
                <Box ml={3}>
                  <Typography variant="h6" component="h3">
                    {title}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    {subTitle}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Link>
        )}
      </Card>

      {showSubFeatures && subFeatures && (
        <div className={classes.subFeatureContainer}>
          <Grid container spacing={2}>
            {subFeatures.map((subFeature, index) => (
              <Grid item xs={12} key={index}>
                <Card className={classes.subFeatureCard}>
                  <Link to={subFeature.to} style={{ textDecoration: 'none', color: 'inherit' }}>
                    <CardContent>
                      <Box display="flex" alignItems="center">
                        <img className={classes.img} src={subFeature.imgUrl} alt={subFeature.title} />
                        <Box ml={3}>
                          <Typography variant="h6" component="h3">
                            {subFeature.title}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {subFeature.subTitle}
                          </Typography>
                        </Box>
                      </Box>
                    </CardContent>
                  </Link>
                </Card>
              </Grid>
            ))}
          </Grid>
        </div>
      )}
    </>
  );
}

export default FeatureBox;
